import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

const apiBaseUrl = String.fromEnvironment('API_BASE_URL', defaultValue: 'http://localhost:8000/api/v1');

class ApiClient {
  String? token;
  Map<String, String> get headers => {'Content-Type': 'application/json', if (token != null) 'Authorization': 'Bearer $token'};
  String error(http.Response r) { try { final d = jsonDecode(r.body); if (d is Map && d.isNotEmpty) { final v = d.values.first; return v is List ? v.first.toString() : v.toString(); } } catch (_) {} return 'خطا در ارتباط با سرور (${r.statusCode})'; }
  Future<void> register({required String username, required String phone, required String firstName, required String lastName, required String password}) async { final r = await http.post(Uri.parse('$apiBaseUrl/auth/register/'), headers: headers, body: jsonEncode({'username':username,'phone':phone,'first_name':firstName,'last_name':lastName,'password':password})); if(r.statusCode!=201) throw Exception(error(r)); }
  Future<void> login(String username,String password) async { final r=await http.post(Uri.parse('$apiBaseUrl/auth/token/'),headers:headers,body:jsonEncode({'username':username,'password':password})); if(r.statusCode!=200) throw Exception(error(r)); token=jsonDecode(r.body)['access']; }
  Future<List<dynamic>> getList(String path) async { final r=await http.get(Uri.parse('$apiBaseUrl/$path/'),headers:headers); if(r.statusCode!=200) throw Exception(error(r)); final d=jsonDecode(r.body); return d is List ? d : (d['results'] ?? []); }
  Future<void> post(String path,Map<String,dynamic> body) async { final r=await http.post(Uri.parse('$apiBaseUrl/$path/'),headers:headers,body:jsonEncode(body)); if(r.statusCode!=201) throw Exception(error(r)); }
  Future<void> addVehicle({required String nickname,required String make,required String model,int? year,required int odometer,required String fuelType}) async { final b=<String,dynamic>{'nickname':nickname,'make':make,'model':model,'current_odometer_km':odometer,'fuel_type':fuelType}; if(year!=null)b['year']=year; await post('vehicles',b); }
  Future<void> addMaintenance({required int vehicle,required String category,required String title,required String date,required int odo,required double cost,String? notes}) async => post('maintenance',{'vehicle':vehicle,'category':category,'title':title,'service_date':date,'odometer_km':odo,'cost':cost,'currency':'IRR','notes':notes??''});
  Future<void> addExpense({required int vehicle,required String category,required String title,required String date,required double amount,int? odo,String? notes}) async => post('expenses',{'vehicle':vehicle,'category':category,'title':title,'expense_date':date,'amount':amount,'currency':'IRR','odometer_km':odo,'notes':notes??''});
}

void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'دستیار خودرو',theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xFF0B8F87),scaffoldBackgroundColor:const Color(0xFFF6F8F8),fontFamily:'Arial'),home:LoginPage(api:ApiClient()));}

InputDecoration deco(String label,IconData icon)=>InputDecoration(labelText:label,prefixIcon:Icon(icon),border:OutlineInputBorder(borderRadius:BorderRadius.circular(14)),filled:true,fillColor:Colors.white);
String fuelLabel(String v)=>{'petrol':'بنزین','diesel':'دیزل','hybrid':'هیبریدی','electric':'برقی','lpg':'LPG','cng':'CNG','other':'سایر'}[v]??v;
String money(dynamic n){final x=(double.tryParse(n.toString())??0).round().toString();return x.replaceAllMapped(RegExp(r'(?<!^)(?=(\d{3})+$)'),(_)=>',');}

